import{_ as o,a0 as p,w as a,s as r,ao as e,I as u,x as t,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具 | LCTT x X-CMD","titleTemplate":false,"description":"Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users","title":"Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具","tag":"201807","desc":""},"relativePath":"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users.md","filePath":"[post].md"}'),d={name:"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users.md"};function b(g,s,y,U,m,w){const n=p("Link");return a(),r("div",null,[s[19]||(s[19]=e(`<h1 id="ubunsys-面向-ubuntu-資深用户的一個高級系統配置工具" tabindex="-1">Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具 <a class="header-anchor" href="#ubunsys-面向-ubuntu-資深用户的一個高級系統配置工具" aria-label="Permalink to “Ubunsys：面向 Ubuntu 資深用户的一個高級系統配置工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-4-1-720x340.png" alt=""></p><p><strong>Ubunsys</strong> 是一個面向 Ubuntu 及其衍生版的基於 Qt 的高級系統工具。高級用户可以使用命令列輕鬆完成大多數配置。不過為了以防萬一某天，你突然不想用命令列了，就可以用 Ubnusys 這個程序來配置你的系統或其衍生系統，如 Linux Mint、Elementary OS 等。Ubunsys 可用來修改系統配置，安裝、刪除、更新包和舊內核，啓用或禁用 <code>sudo</code> 權限，安裝主線內核，更新軟件安裝源，清理垃圾文件，將你的 Ubuntu 系統升級到最新版本等等。以上提到的所有功能都可以通過鼠標點擊完成。你不需要再依賴於命令列模式，下面是你能用 Ubunsys 做到的事：</p><ul><li>安裝、刪除、更新包</li><li>更新和升級軟件源</li><li>安裝主線內核</li><li>刪除舊的和不再使用的內核</li><li>系統整體更新</li><li>將系統升級到下一個可用的版本</li><li>將系統升級到最新的開發版本</li><li>清理系統垃圾文件</li><li>在不輸入密碼的情況下啓用或者禁用 <code>sudo</code> 權限</li><li>當你在終端輸入密碼時使 <code>sudo</code> 密碼可見</li><li>啓用或禁用系統休眠</li><li>啓用或禁用防火牆</li><li>打開、備份和導入 <code>sources.list.d</code> 和 <code>sudoers</code> 文件</li><li>顯示或者隱藏啓動項</li><li>啓用或禁用登錄音效</li><li>配置雙啓動</li><li>啓用或禁用鎖屏</li><li>智能系統更新</li><li>使用腳本管理器更新/一次性執行腳本</li><li>從 <code>git</code> 執行常規用户安裝腳本</li><li>檢查系統完整性和缺失的 GPG 密鑰</li><li>修復網絡</li><li>修復已破損的包</li><li>還有更多功能在開發中</li></ul><p><strong>重要提示：</strong> Ubunsys 不適用於 Ubuntu 新手。它很危險並且仍然不是穩定版。它可能會使你的系統崩潰。如果你剛接觸 Ubuntu 不久，不要使用。但如果你真的很好奇這個應用能做什麼，仔細瀏覽每一個選項，並確定自己能承擔風險。在使用這一應用之前記着備份你自己的重要數據。</p><h3 id="安裝-ubunsys" tabindex="-1">安裝 Ubunsys <a class="header-anchor" href="#安裝-ubunsys" aria-label="Permalink to “安裝 Ubunsys”">​</a></h3><p>Ubunsys 開發者製作了一個 PPA 來簡化安裝過程，Ubunsys 現在可以在 Ubuntu 16.04 LTS、 Ubuntu 17.04 64 位版本上使用。</p><p>逐條執行下面的命令，將 Ubunsys 的 PPA 添加進去，並安裝它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:adgellida/ubunsys</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install ubunsys</span></span></code></pre></div>`,9)),u("p",null,[s[1]||(s[1]=t("如果 PPA 無法使用，你可以在",-1)),i(n,{href:"https://github.com/adgellida/ubunsys/releases"},{default:l(()=>[...s[0]||(s[0]=[t("發佈頁面",-1)])]),_:1}),s[2]||(s[2]=t("根據你自己當前系統，選擇正確的安裝包，直接下載並安裝 Ubunsys。",-1))]),s[20]||(s[20]=e('<h3 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to “用途”">​</a></h3><p>一旦安裝完成，從菜單欄啓動 Ubunsys。下圖是 Ubunsys 主界面。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-1.png" alt=""></p><p>你可以看到，Ubunsys 有四個主要部分，分別是 Packages、Tweaks、System 和 Repair。在每一個標籤項下面都有一個或多個子標籤項以對應不同的操作。</p><p><strong>Packages</strong></p><p>這一部分允許你安裝、刪除和更新包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-2.png" alt=""></p><p><strong>Tweaks</strong></p><p>在這一部分，我們可以對系統進行多種調整，例如：</p><ul><li>打開、備份和導入 <code>sources.list.d</code> 和 <code>sudoers</code> 文件；</li><li>配置雙啓動；</li><li>啓用或禁用登錄音效、防火牆、鎖屏、系統休眠、<code>sudo</code> 權限（在不需要密碼的情況下）同時你還可以針對某一用户啓用或禁用 <code>sudo</code> 權限（在不需要密碼的情況下）；</li><li>在終端中輸入密碼時可見（禁用星號）。</li></ul><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-5.png" alt=""></p><p><strong>System</strong></p><p>這一部分被進一步分成 3 個部分，每個都是針對某一特定用户類型。</p><p><strong>Normal user</strong> 這一標籤下的選項可以：</p><ul><li>更新、升級包和軟件源</li><li>清理系統</li><li>執行常規用户安裝腳本</li></ul><p><strong>Advanced user</strong> 這一標籤下的選項可以：</p><ul><li>清理舊的/無用的內核</li><li>安裝主線內核</li><li>智能包更新</li><li>升級系統</li></ul><p><strong>Developer</strong> 這一部分可以將系統升級到最新的開發版本。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-9.png" alt=""></p><p><strong>Repair</strong></p><p>這是 Ubunsys 的第四個也是最後一個部分。正如名字所示，這一部分能讓我們修復我們的系統、網絡、缺失的 GPG 密鑰，和已經缺失的包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-11.png" alt=""></p><p>正如你所見，Ubunsys 可以在幾次點擊下就能完成諸如系統配置、系統維護和軟件維護之類的任務。你不需要一直依賴於終端。Ubunsys 能幫你完成任何高級任務。再次聲明，我警告你，這個應用不適合新手，而且它並不穩定。所以當你使用的時候，能會出現 bug 或者系統崩潰。在仔細研究過每一個選項的影響之後再使用它。</p><p>謝謝閲讀！</p><h3 id="參考資源" tabindex="-1">參考資源 <a class="header-anchor" href="#參考資源" aria-label="Permalink to “參考資源”">​</a></h3>',25)),u("ul",null,[u("li",null,[i(n,{href:"https://github.com/adgellida/ubunsys"},{default:l(()=>[...s[3]||(s[3]=[t("Ubunsys GitHub Repository",-1)])]),_:1})])]),s[21]||(s[21]=u("hr",null,null,-1)),u("p",null,[s[5]||(s[5]=t("via: ",-1)),i(n,{href:"https://www.ostechnix.com/ubunsys-advanced-system-configuration-utility-ubuntu-power-users/"},{default:l(()=>[...s[4]||(s[4]=[t("https://www.ostechnix.com/ubunsys-advanced-system-configuration-utility-ubuntu-power-users/",-1)])]),_:1})]),u("p",null,[s[10]||(s[10]=t("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[6]||(s[6]=[t("SK",-1)])]),_:1}),s[11]||(s[11]=t(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[7]||(s[7]=[t("lujun9972",-1)])]),_:1}),s[12]||(s[12]=t(" 譯者：",-1)),i(n,{href:"https://github.com/wenwensnow"},{default:l(()=>[...s[8]||(s[8]=[t("wenwensnow",-1)])]),_:1}),s[13]||(s[13]=t(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[9]||(s[9]=[t("wxy",-1)])]),_:1})]),u("p",null,[s[16]||(s[16]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...s[15]||(s[15]=[t("Linux中國",-1)])]),_:1}),s[18]||(s[18]=t(" 榮譽推出",-1))])])}const x=o(d,[["render",b]]);export{T as __pageData,x as default};
